/// <summary>
/// Extension of class <c>SalesInvoiceController</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceController))]
final class METSalesInvoiceController_Extension
{
}

Method.Source:
/// <summary>
///     Executes the report for the print management setting that is currently loaded.
/// </summary>
/// <remarks>
/// The <c>outReports</c> method iterates over print management settings and calls this method for each
/// print management setting that is loaded. Override this method to modify parameters for each print
/// settings if you want to provide different footer text for each print settings loaded for a given
/// report.
/// </remarks>
/// <exception cref="M:Exception::Error">
///     The print management object has not been initialized.
/// </exception>
protected void outputReport()
{
    SalesFormLetterReport_Invoice formLetterReportLoc;

    Args args = this.parmArgs();

    if (args && (args.menuItemName() == menuItemOutputStr(METSalesChargeOnlyCopy)
        || args.menuItemName() == menuItemOutputStr(METSalesChargeOnlyOriginal)))
    {
        SalesTable salestable = custInvoiceJour.salesTable();

        if (formLetterReport is SalesFormLetterReport_Invoice
            && salestable
            && (METSalesOrderTypes::find(salestable.METSalesOrderType).SalesOrderTypeID == METConstants::SalesInvoiceChargeOnly
                || (salestable.checkForReturnCreditInvoice())))
        {
            formLetterReportLoc = formLetterReport;
            PrintMgmtPrintSettingDetail printDetail = formLetterReport.getCurrentPrintSetting();

            //Ensure the print detail is not null
            if (printDetail)
            {
                printDetail.parmReportFormatName(ssrsReportStr(METSalesChargeOnly, Report));
                formLetterReportLoc.metSettCurrentPrinterSettings(printDetail);
                formLetterReport = formLetterReportLoc;
            }
        }
    }

    next outputReport();
    /*
    SysDocuBrandDetails docuBrandDetails;
    METIndustryKeyTable industryKey = METIndustryKeyTable::find(METCustTable::find(custInvoiceJour.InvoiceAccount).IndustryKey);

    select firstonly ReportName, DesignName, METIndustryKey from docuBrandDetails
        where docuBrandDetails.METIndustryKey == industryKey.IndustryKey
            && docuBrandDetails.ReportName == METConstants::METSalesInvoice;

    if(docuBrandDetails)
    {
        str reportname = docuBrandDetails.ReportName;
        str reportdesign = docuBrandDetails.DesignName;
        this.parmReportName(strFmt(METConstants::ReportInfo,reportname,reportdesign));
        this.parmReportName(strFmt(METConstants::ReportInfo,reportname,reportdesign));
    } */

    if (formLetterReportLoc == null)
    {
        this.parmReportName(ssrsReportStr(METSalesInvoice, Report));
    }

}

/// <summary>
/// Report name for the report to be executed. This method is called by the <c>outputReport</c> method to determine which report to execute.
/// </summary>
/// <param name = "_reportName">ReportName</param>
/// <returns>reportName</returns>
public SRSCatalogItemName parmReportName(SRSCatalogItemName _reportName)
{
    SRSCatalogItemName report = next parmReportName(_reportName);

    Set availablePrintMgmtSettings = this.getAvailablePrintMgmtSettings();

    if (!availablePrintMgmtSettings.empty())
    {
        SetEnumerator enumerator = availablePrintMgmtSettings.getEnumerator();

        while (enumerator.moveNext())
        {
            PrintMgmtPrintSettingDetail printDetail = enumerator.current();
            if (printDetail.parmReportFormatName())
            {
                report = printDetail.parmReportFormatName();
                break;
            }
        }
    }

    return report;
}

/// <summary>
/// Retrieves the available Print Management settings for the current context.
/// </summary>
/// <returns>A set of available Print Management settings.</returns>
public Set getAvailablePrintMgmtSettings()
{
    Set ret = new Set(Types::Class);
    Common printMgmtReferencedTable;

    Args args = this.parmArgs();

    journalList = args.record() ? FormLetter::createJournalListCopy(args.record()) : args.object();

    if (journalList)
    {
        journalList.first(custInvoiceJour);
    }

        // Determine where to start looking for Print Mgmt settings
    if (SalesParameters::find().DeleteHeading == NoYes::Yes)
    {
        // The original SalesTable record no longer exists, so skip that Print Mgmt level
        // and start with the customer instead.
        printMgmtReferencedTable = custInvoiceJour.custTable_InvoiceAccount();

        if (printMgmtReferencedTable == null)
        {
            printMgmtReferencedTable = custInvoiceJour.custTable_OrderAccount();
        }
    }
    else
    {
        printMgmtReferencedTable = custInvoiceJour.salesTable();
    }

    PrintMgmtPrintContext printContext;
    PrintMgmtNodeInstance nodeInstance = new PrintMgmtNodeInstance();
    PrintMgmtPrintSetting printSetting;

    nodeInstance.parmNodeDefinition(PrintMgmtNode::construct(SalesParameters::find().DeleteHeading ? PrintMgmtNodeType::CustTable : PrintMgmtNodeType::SalesTable));
    nodeInstance.parmReferencedTableBuffer(printMgmtReferencedTable);

    if (nodeInstance.isValidReference())
    {
        printSetting = new PrintMgmtPrintSetting();
        printContext = new PrintMgmtPrintContext();

        printContext.parmDefaultOriginalPrintJobSettings(new SRSPrintDestinationSettings());
        printContext.parmDefaultCopyPrintJobSettings(new SRSPrintDestinationSettings());
        printContext.parmLanguageId(custInvoiceJour.LanguageId);
        printContext.parmQueryTableBuffer(custInvoiceJour);
        printContext.parmForcePrintJobSettings(true);

        printContext.setHierarchyContext(
            PrintMgmtHierarchyType::Sales,
            PrintMgmtNodeType::Sales,
            PrintMgmtDocumentType::SalesOrderInvoice,
            null);

        printSetting = PrintMgmt::getSettings(printContext);

        if (printSetting)
        {
            for (int i = 1; i <= printSetting.numDetails(); i++)
            {
                ret.add(printSetting.getDetailByPos(i));
            }
        }
    }

    return ret;
}
